import {Link} from '@primer/react'
import type React from 'react'
import type {UpsellData} from './types'

type GetUpsellCopyProps = Pick<
  UpsellData,
  'isAdmin' | 'overagesEnabled' | 'plan' | 'tokenBasedBilling' | 'urls' | 'upsellPlan'
> & {
  quotaResetDate: string
}

export const getUpsellCopy = ({
  isAdmin,
  overagesEnabled,
  plan,
  quotaResetDate,
  tokenBasedBilling,
  urls,
  upsellPlan,
}: GetUpsellCopyProps): {
  body: React.ReactNode
  hideTitle: boolean
  overagesButtonText: string
  showAiCreditsCopy: boolean
  title: string
  upgradeButtonText: string
} => {
  const showAiCreditsCopy = tokenBasedBilling
  const adminLimitText = !isAdmin && plan !== 'individual' ? 'Ask your admin to upgrade to increase your limit. ' : ''

  if (showAiCreditsCopy) {
    return {
      body: (
        <>
          {adminLimitText}
          Copilot code review is available again when your limit resets on {quotaResetDate}.
        </>
      ),
      hideTitle: false,
      overagesButtonText: overagesEnabled ? 'Increase budget' : 'Enable additional usage',
      showAiCreditsCopy,
      title: "You've run out of AI credits for the month",
      upgradeButtonText: 'Upgrade plan',
    }
  }

  return {
    body: (
      <>
        You have reached your monthly limit for{' '}
        <Link inline target="_blank" rel="noopener noreferrer" href={urls.docs}>
          premium requests
        </Link>{' '}
        for Copilot code review. {adminLimitText}Limit resets on {quotaResetDate}.
      </>
    ),
    hideTitle: true,
    overagesButtonText: 'Enable additional requests',
    showAiCreditsCopy,
    title: "You're out of premium requests",
    upgradeButtonText: `Upgrade to ${upsellPlan}`,
  }
}
