import {LinkButton, Banner} from '@primer/react'
import type React from 'react'
import {createPortal} from 'react-dom'
import {useDismissUpsellBanner} from './hooks'
import type {UpsellData} from './types'
import {getUpsellCopy} from './upsell-copy'

interface UpsellBannerProps extends UpsellData {
  repositoryURL: string
  isPullRequestOpen?: boolean
}

export const UpsellBanner: React.FC<UpsellBannerProps> = ({
  repositoryURL,
  isPullRequestOpen,
  urls,
  plan,
  upsellPlan,
  isAdmin,
  quotaReset,
  overagesVisible,
  overagesEnabled,
  tokenBasedBilling,
  bannerDismissKey,
}) => {
  const {container, isDismissed, handleDismiss} = useDismissUpsellBanner(repositoryURL, bannerDismissKey)
  const {body, hideTitle, overagesButtonText, title, upgradeButtonText} = getUpsellCopy({
    isAdmin,
    overagesEnabled,
    plan,
    quotaResetDate: quotaReset.date,
    tokenBasedBilling,
    urls,
    upsellPlan,
  })

  if (!container || isDismissed) return null
  return createPortal(
    <Banner
      title={title}
      hideTitle={hideTitle}
      variant="upsell"
      onDismiss={handleDismiss}
      className={isPullRequestOpen ? 'tmp-mb-3' : 'tmp-my-3'}
    >
      <span>{body}</span>
      {(isAdmin || plan === 'individual') && (
        <div className="d-flex mt-2">
          {!!(urls.upsell && upsellPlan) && (
            <LinkButton target="_blank" rel="noopener noreferrer" href={urls.upsell} className="mr-2">
              {upgradeButtonText}
            </LinkButton>
          )}
          {overagesVisible && (
            <LinkButton
              target="_blank"
              rel="noopener noreferrer"
              href={overagesEnabled ? urls.billing : urls.policy}
              variant={urls.upsell ? 'invisible' : 'default'}
            >
              {overagesButtonText}
            </LinkButton>
          )}
        </div>
      )}
    </Banner>,
    container,
  )
}
